import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Link } from 'react-router-dom';
import '../CSS/login.css';
import axios from 'axios';

function Login({ setLoggedInUser , fetchUserData}) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [errorMessage, setErrorMessage] = useState('');
  const [successMessage, setSuccessMessage] = useState('');
  const navigate = useNavigate();

  // Storing the token in local storage when sign in/sign up in SignIn component
  const handleSignIn = (e) => {
    e.preventDefault();
    // Making a POST request to /signin with axios
    axios
      .post('/signin', { email: email, password: password })
      .then((response) => {
        // Getting the token from the response data
        const token = response.data.token;
        // Storing the token in local storage with 'token' as key
        localStorage.setItem('token', token);
        // Calling fetchUserData function with token as argument
        fetchUserData(token);
      })
      .catch((error) => {
        // Handling any errors
        console.error(error);
      });
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    const response = await fetch('http://localhost:3001/login', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        email,
        password,
      }),
    });
    if (response.ok) {
      const data = await response.json();
      setLoggedInUser(data.user);
      setSuccessMessage('Login successful! Redirecting to home page...');
      setTimeout(() => {
        navigate('/');
      }, 1000);
    } else {
      const data = await response.json();
      setErrorMessage(data.error || 'An error occurred. Please try again.');
    }
  };

  const handleFacebookLoginClick = () => {
    FB.login(function(response) {
      if (response.authResponse) {
        console.log('User logged in successfully!');
        FB.api('/me', { fields: 'name,picture' }, function(response) {
          setLoggedInUser({
            name: response.name,
            profilePicture: response.picture.data.url,
          });
          navigate('/');
        });
      } else {
        console.error('User cancelled login or did not fully authorize.');
      }
    });
  };

  return ( 
    <div className="login-container">
        <div className="login-form">
          <h1>Sign in to MovieMate</h1>
          {errorMessage && <p>{errorMessage}</p>}
          {successMessage && <p>{successMessage}</p>}
          <form onSubmit={handleSubmit}>
            <label htmlFor="email">Email:</label>
            <input
            className='form-input'
              type="email"
              id="email"
              value={email}
              onChange={(event) => setEmail(event.target.value)}
            />
            <br />
            <label htmlFor="password">Password:</label>
            <input
            className='form-input'
              type="password"
              id="password"
              value={password}
              onChange={(event) => setPassword(event.target.value)}
            />
            <br />
            <button className='form-button' type="submit">Sign in</button>
          </form>
          <button className='form-button' onClick={handleFacebookLoginClick}><i className="fab fa-facebook-square"></i> Sign in with Facebook </button>
          <p>
            Don't have an account?{' '}
            <Link to="/signup">Sign up</Link>
          </p>
        </div>
      </div>
  );
}

export default Login;

